#!/usr/bin/env node
'use strict';

/**
 * check-ticket-rbac-sync.cjs (mobile)
 *
 * Verifies this repo's ticketing role-gates never grant access to a role
 * the backend actually disallows. This is the mobile twin of the web
 * repo's script of the same name — see that file's header comment for the
 * full story of the bug this exists to catch (the "raise a ticket" button
 * allowed CUSTOMER_GROUP_ADMIN here when the backend's canCreateTicket
 * middleware never did).
 *
 * What it checks:
 *  1. src/rbac/ticket-capability-matrix.json is a COPY of the canonical
 *     file generated by the backend's
 *     scripts/generate-ticket-capability-matrix.js. This script does NOT
 *     verify the copy is fresh (that would need cross-repo access this
 *     script doesn't have) — see "Real fix vs. today's fix" below.
 *  2. Every role list in src/rbac/ticketCapabilities.ts that's declared as
 *     "deliberately narrower than the backend" (CAN_CHANGE_STATUS_ROLES,
 *     CAN_UPDATE_PRIORITY_ROLES, CAN_SEE_INTERNAL_NOTES_ROLES,
 *     CAN_RAISE_TICKET_ROLES) is checked to be an actual SUBSET of its
 *     corresponding backend capability — i.e. it can only restrict
 *     further, never grant a role the backend wouldn't allow. THIS is the
 *     check that would have caught the CUSTOMER_GROUP_ADMIN bug before it
 *     shipped.
 *
 * Run: node scripts/check-ticket-rbac-sync.cjs
 * Exit 0: no over-permissive drift found.
 * Exit 1: a UI role list grants access to a role the backend disallows —
 *   printed with exactly which role and which capability.
 *
 * --- Real fix vs. today's fix ---
 * The actual, durable fix for "role lists silently drift across repos" is
 * for the backend, web, and mobile code to import ONE shared definition
 * instead of three hand-synced copies — which needs these three repos to
 * live somewhere a single build/package system can reach all of them (a
 * shared internal npm package, or a monorepo). Per the current direction
 * (web and mobile stay as separate, independently git-managed frontend
 * codebases), that restructuring is out of scope for now — this script
 * (and its web twin) is the loud tripwire that replaces "nobody noticed
 * for months" with "the build fails immediately with the exact mismatch."
 */

const path = require('path');

const matrixPath = path.join(
  __dirname,
  '..',
  'src',
  'rbac',
  'ticket-capability-matrix.json',
);

let matrix;
try {
  // eslint-disable-next-line global-require, import/no-dynamic-require
  matrix = require(matrixPath);
} catch (error) {
  console.error(
    `FAIL: could not read ${matrixPath} — has it moved, or was it never copied from the backend's generated file? (${error.message})`,
  );
  process.exit(1);
}

// Local declarations that are DELIBERATELY a subset of a backend
// capability (see ticketCapabilities.ts for the reasoning on each). Map
// each to the backend capability key it must never exceed.
const SUBSET_CHECKS = [
  {
    localName: 'CAN_CHANGE_STATUS_ROLES',
    localRoles: ['ADMIN', 'EMPLOYEE', 'AGENT', 'CUSTOMER_GROUP_ADMIN'],
    backendCapability: 'viewTickets',
  },
  {
    localName: 'CAN_UPDATE_PRIORITY_ROLES (alias of CAN_ASSIGN_ROLES)',
    localRoles: ['ADMIN', 'EMPLOYEE', 'CUSTOMER_GROUP_ADMIN'],
    backendCapability: 'assignTicket',
  },
  {
    localName: 'CAN_SEE_INTERNAL_NOTES_ROLES (alias of CAN_REPLY_ROLES)',
    localRoles: ['ADMIN', 'EMPLOYEE', 'AGENT'],
    backendCapability: 'replyToTicket',
  },
  {
    localName: 'CAN_RAISE_TICKET_ROLES',
    localRoles: ['CUSTOMER'],
    backendCapability: 'createTicket',
  },
];

let failed = false;

SUBSET_CHECKS.forEach(({ localName, localRoles, backendCapability }) => {
  const backendRoles = matrix.capabilities?.[backendCapability]?.allowedRoles;
  if (!backendRoles) {
    console.error(
      `FAIL: canonical matrix has no capability '${backendCapability}' (referenced by ${localName}) — the copied JSON may be stale or the capability was renamed on the backend.`,
    );
    failed = true;
    return;
  }

  const overPermissive = localRoles.filter((role) => !backendRoles.includes(role));
  if (overPermissive.length > 0) {
    console.error(
      `FAIL: ${localName} grants access to [${overPermissive.join(', ')}], but the backend's ` +
        `'${backendCapability}' capability only allows [${backendRoles.join(', ')}]. ` +
        `This is exactly the class of bug that shipped in this app before — fix ` +
        `src/rbac/ticketCapabilities.ts before this can be considered safe.`,
    );
    failed = true;
  } else {
    console.log(
      `OK: ${localName} ⊆ backend '${backendCapability}' [${backendRoles.join(', ')}]`,
    );
  }
});

// Sanity check the seven directly-derived exports actually match the JSON
// verbatim (this should be tautologically true since ticketCapabilities.ts
// reads the JSON directly — but re-verify here in case that file is ever
// changed to hardcode a copy again by mistake).
const DIRECT_CAPABILITIES = [
  'manageWhatsappGroups',
  'manageTicketRules',
  'viewTickets',
  'assignTicket',
  'replyToTicket',
  'closeTicket',
  'createTicket',
];

DIRECT_CAPABILITIES.forEach((capability) => {
  if (!matrix.capabilities?.[capability]) {
    console.error(
      `FAIL: canonical matrix is missing expected capability '${capability}'. Was it renamed on the backend without updating this repo's copy?`,
    );
    failed = true;
  }
});

if (failed) {
  console.error('\nRBAC sync check FAILED — see above.');
  process.exit(1);
}

console.log('\nRBAC sync check passed — no over-permissive drift from the backend found.');
process.exit(0);
